//! ADNL-TCP liteclient tests for `iroha_sccp_rpc::ton`.
//!
//! An in-process mock liteserver implements the server side of the ADNL-TCP
//! handshake independently (Ed25519 private scalar, AES-256-CTR, SHA-256
//! framing) and replays `liteServer.*` answers recorded from a TON mainnet
//! liteserver (`fixtures/sccp/rpc/ton/transport`), matching every request
//! byte-for-byte against the recorded one. A handshake and framing vector
//! generated by an independent implementation pins the client's bytes.
//! Synthetic misbehaviour (liteserver errors, stalls, bad checksums, bad
//! packet sizes, foreign query ids, mismatched answers, refused handshakes)
//! drives failover. Nothing here touches the network.

use std::{
    collections::BTreeMap,
    fs,
    io::{Read as _, Write as _},
    net::{IpAddr, SocketAddr, SocketAddrV4, TcpListener, TcpStream},
    num::NonZeroU32,
    path::{Path, PathBuf},
    sync::{
        Arc, Mutex,
        atomic::{AtomicBool, AtomicUsize, Ordering},
    },
    thread::{self, JoinHandle},
    time::{Duration, Instant},
};

use aes::{
    Aes256,
    cipher::{KeyIvInit, StreamCipher},
};
use curve25519_dalek::edwards::CompressedEdwardsY;
use ed25519_dalek::SigningKey;
use iroha_config::parameters::actual::SccpTonLiteserver;
use iroha_sccp_rpc::{
    endpoints::{Backoff, FailoverPolicy, PollBudget, Sleeper, start_index},
    ton::{
        AccountId, AdnlConnection, AdnlError, BlockId, BlockIdExt, LiteAnswer, LiteClient,
        LiteClientConfig, LiteClientError, LiteQuery, LiteServer, LiteServerSet, LookupKey, Stage,
        WaitMasterchainSeqno,
        adnl::{
            self, ADNL_MESSAGE_ANSWER, ADNL_MESSAGE_QUERY, AdnlMessage, HandshakeSecrets,
            SessionCiphers, TCP_PING, TCP_PONG,
        },
        schema::{
            self, BlockLink, MasterchainInfo, SHARD_FULL, SignatureSet, TransactionList, method_id,
        },
        tl::{TlReader, TlWriter},
    },
};
use norito::json::Value;
use sha2::{Digest, Sha256};

type Cipher = ctr::Ctr128BE<Aes256>;

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/sccp/rpc/ton/transport")
}

fn fixture_json(name: &str) -> Value {
    let path = fixtures_dir().join(name);
    let text =
        fs::read_to_string(&path).unwrap_or_else(|error| panic!("{}: {error}", path.display()));
    norito::json::parse_value(&text).expect("fixture JSON")
}

fn hex_field(value: &Value, field: &str) -> Vec<u8> {
    hex::decode(
        value
            .get(field)
            .and_then(Value::as_str)
            .unwrap_or_else(|| panic!("missing `{field}`")),
    )
    .expect("hex")
}

fn array<const N: usize>(bytes: &[u8]) -> [u8; N] {
    bytes.try_into().expect("fixed-size field")
}

/// One recorded exchange: the `data` of `liteServer.query` and the raw answer.
#[derive(Clone)]
struct Exchange {
    request: Vec<u8>,
    answer: Vec<u8>,
}

struct Recording {
    index: Value,
    exchanges: BTreeMap<String, Exchange>,
}

impl Recording {
    fn load() -> Self {
        let index = fixture_json("recorded.json");
        let exchanges = index
            .get("exchanges")
            .and_then(Value::as_object)
            .expect("exchanges")
            .iter()
            .map(|(name, entry)| {
                let answer_path = fixtures_dir().join(
                    entry
                        .get("answer")
                        .and_then(Value::as_str)
                        .expect("answer path"),
                );
                let answer = fs::read(&answer_path).expect("answer file");
                assert_eq!(
                    entry
                        .get("answer_bytes")
                        .and_then(Value::as_u64)
                        .and_then(|bytes| usize::try_from(bytes).ok()),
                    Some(answer.len()),
                    "{name}"
                );
                (
                    name.clone(),
                    Exchange {
                        request: hex_field(entry, "request"),
                        answer,
                    },
                )
            })
            .collect();
        Self { index, exchanges }
    }

    fn exchange(&self, name: &str) -> &Exchange {
        self.exchanges
            .get(name)
            .unwrap_or_else(|| panic!("no recorded exchange `{name}`"))
    }

    fn decode<T: LiteAnswer>(&self, name: &str) -> T {
        T::decode_answer(&self.exchange(name).answer).expect("recorded answer decodes")
    }

    fn number(&self, field: &str) -> u64 {
        self.index
            .get(field)
            .and_then(Value::as_u64)
            .unwrap_or_else(|| panic!("missing `{field}`"))
    }

    fn account(&self) -> AccountId {
        let text = self
            .index
            .get("account")
            .and_then(Value::as_str)
            .expect("account");
        let (workchain, address) = text.split_once(':').expect("raw address");
        AccountId {
            workchain: workchain.parse().expect("workchain"),
            address: array(&hex::decode(address).expect("hex")),
        }
    }

    /// Replays by exact request bytes; anything else gets a non-failover
    /// `liteServer.error` naming the request.
    fn handler(self: &Arc<Self>) -> Handler {
        let recording = Arc::clone(self);
        Arc::new(move |data: &[u8]| {
            recording
                .exchanges
                .values()
                .find(|exchange| exchange.request == data)
                .map_or_else(
                    || {
                        Reply::Answer(lite_error(
                            -999,
                            &format!("unrecorded {}", hex::encode(data)),
                        ))
                    },
                    |exchange| Reply::Answer(exchange.answer.clone()),
                )
        })
    }
}

fn lite_error(code: i32, message: &str) -> Vec<u8> {
    let mut writer = TlWriter::boxed(schema::id::ERROR);
    writer.i32(code).bytes(message.as_bytes()).expect("bytes");
    writer.finish()
}

// ---------------------------------------------------------------------------
// Mock liteserver (independent server-side ADNL-TCP)
// ---------------------------------------------------------------------------

/// What the mock does with one query.
#[derive(Clone)]
enum Reply {
    /// Answer with these TL bytes.
    Answer(Vec<u8>),
    /// Send `tcp.ping`, require the client's `tcp.pong`, then answer.
    PingThenAnswer(Vec<u8>),
    /// Answer under a query id the client never sent.
    ForeignQueryId(Vec<u8>),
    /// Answer with a corrupted checksum.
    CorruptChecksum(Vec<u8>),
    /// Send only an encrypted size field announcing this many bytes.
    AnnounceSize(u32),
    /// Answer, then close the connection.
    AnswerThenClose(Vec<u8>),
    /// Send the first half of the answer packet, then close.
    Truncate(Vec<u8>),
    /// Stay silent for this long, then close.
    Stall(Duration),
}

type Handler = Arc<dyn Fn(&[u8]) -> Reply + Send + Sync>;

#[derive(Default)]
struct Stats {
    connections: AtomicUsize,
    handshakes: AtomicUsize,
    pings: AtomicUsize,
    queries: Mutex<Vec<Vec<u8>>>,
    handshake_packets: Mutex<Vec<Vec<u8>>>,
}

impl Stats {
    fn queries(&self) -> Vec<Vec<u8>> {
        self.queries.lock().expect("stats").clone()
    }
}

struct MockLiteServer {
    address: SocketAddr,
    public_key: [u8; 32],
    stats: Arc<Stats>,
    stop: Arc<AtomicBool>,
    accept: Option<JoinHandle<()>>,
}

impl MockLiteServer {
    fn start(key: SigningKey, handler: Handler) -> Self {
        Self::start_with(key, handler, false)
    }

    /// `close_on_handshake`: read the handshake and close without confirming.
    fn start_with(key: SigningKey, handler: Handler, close_on_handshake: bool) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind mock liteserver");
        let address = listener.local_addr().expect("mock address");
        let stats = Arc::new(Stats::default());
        let stop = Arc::new(AtomicBool::new(false));
        let public_key = key.verifying_key().to_bytes();
        let accept = {
            let stats = Arc::clone(&stats);
            let stop = Arc::clone(&stop);
            thread::spawn(move || {
                for stream in listener.incoming() {
                    if stop.load(Ordering::SeqCst) {
                        break;
                    }
                    let Ok(stream) = stream else { continue };
                    stats.connections.fetch_add(1, Ordering::SeqCst);
                    let stats = Arc::clone(&stats);
                    let handler = Arc::clone(&handler);
                    let key = key.clone();
                    thread::spawn(move || {
                        serve(stream, &key, &handler, &stats, close_on_handshake);
                    });
                }
            })
        };
        Self {
            address,
            public_key,
            stats,
            stop,
            accept: Some(accept),
        }
    }

    /// The `<ipv4>:<port>:<base64 key>` configuration entry.
    fn entry(&self) -> String {
        let IpAddr::V4(ip) = self.address.ip() else {
            panic!("the mock listens on IPv4");
        };
        SccpTonLiteserver {
            address: SocketAddrV4::new(ip, self.address.port()),
            public_key: self.public_key,
        }
        .to_string()
    }

    fn server(&self) -> LiteServer {
        LiteServer::new(self.address, self.public_key).expect("mock liteserver")
    }
}

impl Drop for MockLiteServer {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
        let _ = TcpStream::connect(self.address);
        if let Some(accept) = self.accept.take() {
            let _ = accept.join();
        }
    }
}

/// The server's session: decrypts what the client sends, encrypts replies.
struct ServerSession {
    receive: Cipher,
    send: Cipher,
    nonce_counter: u8,
}

impl ServerSession {
    fn seal(&mut self, payload: &[u8]) -> Vec<u8> {
        self.nonce_counter = self.nonce_counter.wrapping_add(1);
        let nonce = [self.nonce_counter; 32];
        let size = u32::try_from(payload.len() + 64).expect("packet size");
        let mut packet = size.to_le_bytes().to_vec();
        packet.extend_from_slice(&nonce);
        packet.extend_from_slice(payload);
        let checksum = Sha256::digest(&packet[4..]);
        packet.extend_from_slice(&checksum);
        self.send.apply_keystream(&mut packet);
        packet
    }

    fn open(&mut self, stream: &mut TcpStream) -> Option<Vec<u8>> {
        let mut size = [0_u8; 4];
        stream.read_exact(&mut size).ok()?;
        self.receive.apply_keystream(&mut size);
        let size = usize::try_from(u32::from_le_bytes(size)).expect("size");
        assert!((64..=1 << 24).contains(&size), "client packet size {size}");
        let mut body = vec![0_u8; size];
        stream.read_exact(&mut body).ok()?;
        self.receive.apply_keystream(&mut body);
        let (content, checksum) = body.split_at(size - 32);
        assert_eq!(
            Sha256::digest(content).as_slice(),
            checksum,
            "client checksum"
        );
        Some(content[32..].to_vec())
    }
}

/// The server half of the handshake, derived from the Ed25519 private scalar.
fn accept_handshake(packet: &[u8; 256], key: &SigningKey) -> Option<ServerSession> {
    let mut id_preimage = adnl::PUB_ED25519.to_le_bytes().to_vec();
    id_preimage.extend_from_slice(key.verifying_key().as_bytes());
    if packet[..32] != Sha256::digest(&id_preimage)[..] {
        return None;
    }
    let client = CompressedEdwardsY(array(&packet[32..64]))
        .decompress()?
        .to_montgomery();
    let shared = client.mul_clamped(key.to_scalar_bytes()).to_bytes();
    let hash = &packet[64..96];
    let mut handshake_key = [0_u8; 32];
    handshake_key[..16].copy_from_slice(&shared[..16]);
    handshake_key[16..].copy_from_slice(&hash[16..]);
    let mut iv = [0_u8; 16];
    iv[..4].copy_from_slice(&hash[..4]);
    iv[4..].copy_from_slice(&shared[20..]);
    let mut params = packet[96..].to_vec();
    Cipher::new(&handshake_key.into(), &iv.into()).apply_keystream(&mut params);
    assert_eq!(Sha256::digest(&params).as_slice(), hash, "params hash");
    let cipher = |key: &[u8], iv: &[u8]| {
        Cipher::new(
            &<[u8; 32]>::try_from(key).expect("key").into(),
            &<[u8; 16]>::try_from(iv).expect("iv").into(),
        )
    };
    Some(ServerSession {
        receive: cipher(&params[32..64], &params[80..96]),
        send: cipher(&params[0..32], &params[64..80]),
        nonce_counter: 0,
    })
}

fn serve(
    mut stream: TcpStream,
    key: &SigningKey,
    handler: &Handler,
    stats: &Stats,
    close_on_handshake: bool,
) {
    let _ = stream.set_nonblocking(false);
    let mut packet = [0_u8; 256];
    if stream.read_exact(&mut packet).is_err() {
        return;
    }
    stats
        .handshake_packets
        .lock()
        .expect("stats")
        .push(packet.to_vec());
    if close_on_handshake {
        return;
    }
    // A handshake for another key is dropped, as a liteserver does.
    let Some(mut session) = accept_handshake(&packet, key) else {
        return;
    };
    stats.handshakes.fetch_add(1, Ordering::SeqCst);
    if stream.write_all(&session.seal(&[])).is_err() {
        return;
    }
    while let Some(payload) = session.open(&mut stream) {
        let mut reader = TlReader::new(&payload);
        match reader.u32().expect("constructor") {
            TCP_PING => {
                stats.pings.fetch_add(1, Ordering::SeqCst);
                let random_id = reader.i64().expect("ping id");
                let _ = stream.write_all(&session.seal(&adnl::encode_ping(TCP_PONG, random_id)));
            }
            ADNL_MESSAGE_QUERY => {
                let query_id = reader.int256().expect("query id");
                let query = reader.bytes().expect("query");
                reader.finish().expect("one query");
                let (wait, request) = schema::unwrap_query(query).expect("liteServer.query");
                let mut data = Vec::new();
                if let Some(wait) = wait {
                    data.extend_from_slice(&schema::id::WAIT_MASTERCHAIN_SEQNO.to_le_bytes());
                    data.extend_from_slice(&wait.seqno.to_le_bytes());
                    data.extend_from_slice(&wait.timeout_ms.to_le_bytes());
                }
                data.extend_from_slice(&request);
                stats.queries.lock().expect("stats").push(data.clone());
                if !reply(&mut stream, &mut session, &query_id, handler(&data)) {
                    return;
                }
            }
            other => panic!("unexpected client message {other:#x}"),
        }
    }
}

fn answer_message(query_id: &[u8; 32], answer: &[u8]) -> Vec<u8> {
    let mut writer = TlWriter::boxed(ADNL_MESSAGE_ANSWER);
    writer.int256(query_id).bytes(answer).expect("bytes");
    writer.finish()
}

/// Acts out one reply; returns whether the connection stays open.
fn reply(
    stream: &mut TcpStream,
    session: &mut ServerSession,
    query_id: &[u8; 32],
    reply: Reply,
) -> bool {
    match reply {
        Reply::Answer(answer) => stream
            .write_all(&session.seal(&answer_message(query_id, &answer)))
            .is_ok(),
        Reply::PingThenAnswer(answer) => {
            let _ = stream.write_all(&session.seal(&adnl::encode_ping(TCP_PING, 4242)));
            let pong = session.open(stream).expect("client pong");
            assert_eq!(pong, adnl::encode_ping(TCP_PONG, 4242));
            stream
                .write_all(&session.seal(&answer_message(query_id, &answer)))
                .is_ok()
        }
        Reply::ForeignQueryId(answer) => {
            let _ = stream.write_all(&session.seal(&answer_message(&[0xEE; 32], &answer)));
            true
        }
        Reply::CorruptChecksum(answer) => {
            let mut packet = session.seal(&answer_message(query_id, &answer));
            let last = packet.len() - 1;
            packet[last] ^= 0x80;
            let _ = stream.write_all(&packet);
            true
        }
        Reply::AnnounceSize(size) => {
            let mut field = size.to_le_bytes();
            session.send.apply_keystream(&mut field);
            let _ = stream.write_all(&field);
            thread::sleep(Duration::from_millis(200));
            false
        }
        Reply::AnswerThenClose(answer) => {
            let _ = stream.write_all(&session.seal(&answer_message(query_id, &answer)));
            false
        }
        Reply::Truncate(answer) => {
            let packet = session.seal(&answer_message(query_id, &answer));
            let _ = stream.write_all(&packet[..packet.len() / 2]);
            false
        }
        Reply::Stall(duration) => {
            thread::sleep(duration);
            false
        }
    }
}

fn signing_key(label: &str) -> SigningKey {
    SigningKey::from_bytes(&Sha256::digest(label.as_bytes()).into())
}

// ---------------------------------------------------------------------------
// Client helpers
