#[test]
fn failover_moves_to_the_next_liteserver_and_sticks() {
    let recording = Arc::new(Recording::load());
    let not_ready = MockLiteServer::start(
        signing_key("not ready"),
        Arc::new(|_: &[u8]| Reply::Answer(lite_error(651, "block is not applied"))),
    );
    let healthy = replay_server(&recording, "healthy");
    let client = client(&[&not_ready, &healthy], config(Duration::from_secs(10)), 1);
    let block = masterchain_block(&recording);
    assert_eq!(client.get_block(block).expect("failover").id, block);
    assert_eq!(client.servers().preferred(), 1);
    assert_eq!(not_ready.stats.queries().len(), 1);
    // The next query starts at the liteserver that answered.
    client.get_masterchain_info().expect("preferred server");
    assert_eq!(not_ready.stats.queries().len(), 1);
    assert_eq!(healthy.stats.queries().len(), 2);
    assert_eq!(healthy.stats.connections.load(Ordering::SeqCst), 1);
    // Rotation moves the start back to the first server.
    client.servers().rotate_preferred();
    client.get_masterchain_info().expect("after rotation");
    assert_eq!(not_ready.stats.queries().len(), 2);
}

#[test]
fn timeouts_fail_over_and_drop_the_session() {
    let recording = Arc::new(Recording::load());
    let stalled = MockLiteServer::start(
        signing_key("stalled"),
        Arc::new(|_: &[u8]| Reply::Stall(Duration::from_secs(2))),
    );
    let healthy = replay_server(&recording, "after stall");
    let client = client(&[&stalled, &healthy], config(Duration::from_millis(300)), 1);
    let started = Instant::now();
    let info = client.get_masterchain_info().expect("second liteserver");
    assert!(info.last.is_masterchain());
    assert!(started.elapsed() < Duration::from_secs(2));

    // With the stalled server alone every round times out.
    let alone = self::client(&[&stalled], config(Duration::from_millis(200)), 2);
    let error = alone.get_time().expect_err("stalled");
    let LiteClientError::Exhausted { failures } = &error else {
        panic!("unexpected {error:?}");
    };
    assert_eq!(failures.len(), 2);
    assert!(failures.iter().all(|failure| matches!(
        failure.error,
        LiteClientError::Adnl {
            stage: Stage::Query,
            error: AdnlError::Timeout,
            ..
        }
    )));
    assert!(!alone.is_connected());
}

#[test]
fn answers_above_the_query_cap_fail_over_unread() {
    let recording = Arc::new(Recording::load());
    // A `getTime` answer far above its cap (but within the packet bound).
    let bloated = MockLiteServer::start(
        signing_key("bloated"),
        Arc::new(|_: &[u8]| Reply::Answer(vec![0; schema::SMALL_ANSWER_BYTES + 1_024])),
    );
    let healthy = replay_server(&recording, "after bloat");
    let client = client(&[&bloated, &healthy], config(Duration::from_secs(10)), 1);
    assert!(LiteQuery::GetTime.max_answer_bytes() < client.config().max_packet_bytes);
    let time = client.get_time().expect("second liteserver");
    assert!(time.now > 1_700_000_000);
    assert_eq!(client.servers().preferred(), 1);

    let (error, connected) = only_failure(&bloated, config(Duration::from_secs(10)));
    assert!(
        matches!(
            error,
            LiteClientError::Adnl {
                stage: Stage::Query,
                error: AdnlError::PacketTooLarge { limit, .. },
                ..
            } if limit == adnl::answer_packet_bytes(schema::SMALL_ANSWER_BYTES)
        ),
        "{error:?}"
    );
    assert!(!connected, "the unread packet breaks the session");
}

#[test]
fn poll_budgets_bound_liteserver_queries() {
    let recording = Arc::new(Recording::load());
    let stalled = MockLiteServer::start(
        signing_key("budget stalled"),
        Arc::new(|_: &[u8]| Reply::Stall(Duration::from_secs(1))),
    );
    let healthy = replay_server(&recording, "budget healthy");
    let budget = PollBudget::new();
    let client = client(&[&stalled, &healthy], config(Duration::from_secs(5)), 2)
        .with_budget(budget.clone());
    {
        let _poll = budget.start(Duration::from_millis(300));
        let started = Instant::now();
        let error = client.get_time().expect_err("budget runs out");
        assert!(
            started.elapsed() < Duration::from_secs(2),
            "{:?}",
            started.elapsed()
        );
        let LiteClientError::BudgetExhausted { failures } = &error else {
            panic!("unexpected {error:?}");
        };
        assert_eq!(failures.len(), 1);
        assert!(
            healthy.stats.queries().is_empty(),
            "no attempt past the budget"
        );
    }
    // Without a deadline the query fails over as usual.
    assert!(client.get_time().expect("second liteserver").now > 1_700_000_000);
}

#[test]
fn keeper_lists_start_at_seeded_liteservers() {
    let recording = Arc::new(Recording::load());
    let servers: Vec<MockLiteServer> = (0..3)
        .map(|index| replay_server(&recording, &format!("seeded {index}")))
        .collect();
    let mut seeds = [None; 3];
    for seed in 0_u64..256 {
        seeds[start_index(seed, 3)].get_or_insert(seed);
    }
    for (index, seed) in seeds.into_iter().enumerate() {
        let seed = seed.expect("every index is some seed's start");
        let set = LiteServerSet::new(servers.iter().map(MockLiteServer::server))
            .expect("servers")
            .with_seeded_start(seed);
        let client = LiteClient::new(set, config(Duration::from_secs(10)), policy(1));
        client.get_time().expect("seeded liteserver");
        assert_eq!(servers[index].stats.queries().len(), 1, "seed {seed}");
    }
}

/// A single-server client whose only attempt fails; returns that failure.
fn only_failure(server: &MockLiteServer, config: LiteClientConfig) -> (LiteClientError, bool) {
    let client = client(&[server], config, 1);
    let error = client.get_time().expect_err("attempt fails");
    let connected = client.is_connected();
    (error.last_failure().clone(), connected)
}

#[test]
fn checksum_and_framing_negatives_break_the_session() {
    let time = {
        let mut writer = TlWriter::boxed(schema::id::CURRENT_TIME);
        writer.u32(1_790_000_000);
        writer.finish()
    };
    let cases: Vec<(Reply, AdnlError, LiteClientConfig)> = vec![
        (
            Reply::CorruptChecksum(time.clone()),
            AdnlError::Checksum,
            config(Duration::from_secs(5)),
        ),
        (
            Reply::AnnounceSize(10),
            AdnlError::PacketTooShort { size: 10 },
            config(Duration::from_secs(5)),
        ),
        (
            Reply::AnnounceSize(1 << 20),
            AdnlError::PacketTooLarge {
                size: 1 << 20,
                limit: 4096,
            },
            config(Duration::from_secs(5)).with_max_packet_bytes(4096),
        ),
        (
            Reply::Truncate(time.clone()),
            AdnlError::Closed,
            config(Duration::from_secs(5)),
        ),
    ];
    for (index, (behaviour, expected, config)) in cases.into_iter().enumerate() {
        let server = MockLiteServer::start(
            signing_key(&format!("framing {index}")),
            Arc::new(move |_: &[u8]| behaviour.clone()),
        );
        let (error, connected) = only_failure(&server, config);
        match (&error, &expected) {
            (LiteClientError::Adnl { stage, error, .. }, expected) => {
                assert_eq!(*stage, Stage::Query, "case {index}");
                assert_eq!(error, expected, "case {index}");
                assert!(!connected, "case {index}: the session must be dropped");
            }
            _ => panic!("case {index}: unexpected {error:?}"),
        }
    }

    // An answer to a query the client never sent.
    let foreign = MockLiteServer::start(
        signing_key("foreign query id"),
        Arc::new(move |_: &[u8]| Reply::ForeignQueryId(time.clone())),
    );
    let (error, connected) = only_failure(&foreign, config(Duration::from_secs(5)));
    assert!(
        matches!(
            error,
            LiteClientError::Adnl {
                error: AdnlError::Protocol(_),
                ..
            }
        ),
        "{error:?}"
    );
    assert!(!connected);
}

#[test]
fn refused_handshakes_fail_over() {
    let recording = Arc::new(Recording::load());
    // The server holds another key than the one configured: it drops the
    // handshake for the unknown key id.
    let impostor = MockLiteServer::start(signing_key("real key"), recording.handler());
    let wrong_key = LiteServer::new(
        impostor.address,
        signing_key("configured key").verifying_key().to_bytes(),
    )
    .expect("server");
    // A server that reads the handshake and closes.
    let closing = MockLiteServer::start_with(signing_key("closing"), recording.handler(), true);
    let healthy = replay_server(&recording, "healthy after refusals");
    let servers =
        LiteServerSet::new([wrong_key, closing.server(), healthy.server()]).expect("servers");
    let client = LiteClient::new(servers, config(Duration::from_secs(5)), policy(1));
    client.get_masterchain_info().expect("third liteserver");
    assert_eq!(client.servers().preferred(), 2);
    assert_eq!(impostor.stats.handshakes.load(Ordering::SeqCst), 0);
    assert_eq!(
        impostor
            .stats
            .handshake_packets
            .lock()
            .expect("stats")
            .len(),
        1
    );
    assert_eq!(closing.stats.handshakes.load(Ordering::SeqCst), 0);

    // Alone, a refused handshake is a connect-stage failure.
    let alone = LiteClient::new(
        LiteServerSet::parse(&[&closing.entry()]).expect("servers"),
        config(Duration::from_secs(5)),
        policy(1),
    );
    let error = alone.get_time().expect_err("refused");
    assert!(
        matches!(
            error.last_failure(),
            LiteClientError::Adnl {
                stage: Stage::Connect,
                error: AdnlError::Closed,
                ..
            }
        ),
        "{error:?}"
    );
}

#[test]
fn mismatched_answers_fail_over() {
    let recording = Arc::new(Recording::load());
    let key_header = recording.exchange("lookup_key_block_seqno").answer.clone();
    let wrong_type = recording.exchange("get_masterchain_info").answer.clone();
    // Answers `getBlock` with masterchain info and everything else with the
    // key block's header.
    let liar = MockLiteServer::start(
        signing_key("liar"),
        Arc::new(move |data: &[u8]| {
            if data[..4] == schema::id::GET_BLOCK.to_le_bytes() {
                Reply::Answer(wrong_type.clone())
            } else {
                Reply::Answer(key_header.clone())
            }
        }),
    );
    let healthy = replay_server(&recording, "honest");
    let client = client(&[&liar, &healthy], config(Duration::from_secs(5)), 1);
    let block = masterchain_block(&recording);
    assert_eq!(client.get_block_header(block, 0).expect("header").id, block);
    client.servers().rotate_preferred();
    assert_eq!(client.get_block(block).expect("block").id, block);

    let liar_alone = self::client(&[&liar], config(Duration::from_secs(5)), 1);
    let error = liar_alone
        .get_block_header(block, 0)
        .expect_err("another block");
    assert!(
        matches!(
            error.last_failure(),
            LiteClientError::InvalidResponse { detail, .. } if detail.contains("another block")
        ),
        "{error:?}"
    );
    let error = liar_alone.get_block(block).expect_err("wrong answer type");
    assert!(
        matches!(
            error.last_failure(),
            LiteClientError::InvalidResponse { detail, .. } if detail.contains("liteServer.blockData")
        ),
        "{error:?}"
    );
    // A malformed answer does not break the session.
    assert!(liar_alone.is_connected());
}

