#[test]
fn keep_alive_probes_idle_sessions_and_reconnects() {
    let recording = Arc::new(Recording::load());
    let server = replay_server(&recording, "keep-alive");
    let eager = LiteClientConfig {
        keepalive_interval: Duration::ZERO,
        ..config(Duration::from_secs(5))
    };
    let client = client(&[&server], eager, 1);
    assert!(!client.keep_alive().expect("no session"));
    client.get_masterchain_info().expect("first query");
    assert_eq!(server.stats.pings.load(Ordering::SeqCst), 0);
    // Reusing an idle session probes it first.
    client.get_time().expect("second query");
    assert_eq!(server.stats.pings.load(Ordering::SeqCst), 1);
    assert!(client.keep_alive().expect("probe"));
    assert_eq!(server.stats.pings.load(Ordering::SeqCst), 2);
    assert_eq!(server.stats.connections.load(Ordering::SeqCst), 1);
    client.disconnect();
    assert!(!client.is_connected());
    client.get_time().expect("reconnects");
    assert_eq!(server.stats.connections.load(Ordering::SeqCst), 2);

    // A session the server closed fails its probe and is replaced.
    let info = recording.exchange("get_masterchain_info").answer.clone();
    let closing = MockLiteServer::start(
        signing_key("closes after answering"),
        Arc::new(move |_: &[u8]| Reply::AnswerThenClose(info.clone())),
    );
    let client = self::client(&[&closing], eager, 1);
    client.get_masterchain_info().expect("first session");
    client.get_masterchain_info().expect("second session");
    assert_eq!(closing.stats.connections.load(Ordering::SeqCst), 2);
    let _ = client.get_masterchain_info();
    let error = client.keep_alive().expect_err("closed session");
    assert!(matches!(
        error,
        LiteClientError::Adnl {
            stage: Stage::KeepAlive,
            ..
        }
    ));
    assert!(!client.is_connected());
}

